import os
os.environ['OPENBLAS_NUM_THREADS']='1'
import numpy as np,pandas as pd
from scipy.optimize import least_squares
from sklearn.preprocessing import StandardScaler,OneHotEncoder,SplineTransformer
from sklearn.model_selection import KFold
D=pd.read_csv('alloy_pair_constrained_train.csv'); y=D.target.to_numpy(); comp=list(D.columns[:12]);proc=list(D.columns[13:17]);cats=['heat_treatment','route'];kf=KFold(5,shuffle=True,random_state=42)

class PeakModel:
 def __init__(self,kind='sqrtlinear',degree=2,peakvars=['aging_temp','cooling_rate']):
  self.kind=kind;self.degree=degree;self.peakvars=peakvars
 def base(self,D,fit=False):
  if fit:self.o=OneHotEncoder(sparse_output=False,drop='first').fit(D[cats]);self.sc=StandardScaler().fit(D[proc])
  P=self.sc.transform(D[proc]);B=np.column_stack([P**k for k in range(1,self.degree+1)])
  if self.kind=='sqrtlinear': C=np.column_stack([np.sqrt(D[comp]),D[comp]])
  if self.kind=='sqrt': C=np.sqrt(D[comp]).values
  if self.kind=='spline':
   if fit:self.s=SplineTransformer(n_knots=4).fit(D[comp])
   C=self.s.transform(D[comp])
  return np.column_stack([np.ones(len(D)),C,B,self.o.transform(D[cats])])
 def gauss(self,p,D):
  return np.exp(-np.sum([((D[c].to_numpy()-p[2*i])/p[2*i+1])**2 for i,c in enumerate(self.peakvars)],axis=0))
 def fit(self,D,y):
  A=self.base(D,True);self.A=A
  # Tiny ridge only to avoid singular basis in splines
  self.Ai=np.linalg.pinv(A,rcond=1e-8);self.yy=y-A@(self.Ai@y)
  def residual(p):
   g=self.gauss(p,D);gg=g-A@(self.Ai@g)
   self.amp=gg@self.yy/(gg@gg)
   return self.yy-self.amp*gg
  initial={'aging_temp':[600,40], 'cooling_rate':[35,10], 'aging_time':[32,20], 'solutionizing_temp':[1120,150]}
  bounds={'aging_temp':([500,5],[700,140]),'cooling_rate':([5,2],[75,60]),'aging_time':([1,3],[50,100]),'solutionizing_temp':([950,30],[1250,600])}
  x0=np.concatenate([initial[c] for c in self.peakvars]);lo=np.concatenate([bounds[c][0] for c in self.peakvars]);hi=np.concatenate([bounds[c][1] for c in self.peakvars])
  opt=least_squares(residual,x0,bounds=(lo,hi),max_nfev=100,ftol=1e-8)
  residual(opt.x);self.p=opt.x;self.coef=self.Ai@(y-self.amp*self.gauss(self.p,D));return self
 def predict(self,D):
  return self.base(D)@self.coef+self.amp*self.gauss(self.p,D)

if __name__=='__main__':
 for kind in ['sqrt','sqrtlinear','spline']:
  for deg in [2,3]:
   for variables in [['aging_temp','cooling_rate'],['aging_temp','cooling_rate','aging_time'],['aging_temp','cooling_rate','solutionizing_temp']]:
    p=np.zeros(len(y))
    for it,iv in kf.split(D):
     m=PeakModel(kind,deg,variables).fit(D.iloc[it],y[it]);p[iv]=m.predict(D.iloc[iv])
    m.fit(D,y)
    print(kind,deg,variables,'CV',round(np.mean((y-p)**2)**.5,4),'train',round(np.mean((y-m.predict(D))**2)**.5,4),'peak',m.p.round(3),'amplitude',round(m.amp,3),flush=True)
 m=PeakModel('sqrtlinear',2).fit(D,y)
 names=['constant']+['sqrt_'+c for c in comp]+comp+[c+'^'+str(k) for k in range(1,3) for c in proc]+list(m.o.get_feature_names_out())
 print('coefs',list(zip(names,m.coef.round(3))))
 r=y-m.predict(D);print(pd.DataFrame({'res':r}).reindex(np.argsort(-np.abs(r))[:15]).join(D).to_string())

