active=['Cr','Ni','Mo','V','Nb','Co','Ti'];other=['C','Mn','Si','Al','Cu']
class SaturationModel:
 def __init__(self,kind='exp',degree=2):
  self.kind=[kind]*7 if isinstance(kind,str) else kind;self.degree=degree
 def mat(self,p,D,fit=False):
  if fit:self.o=OneHotEncoder(sparse_output=False,drop='first').fit(D[cats]);self.sc=StandardScaler().fit(D[proc])
  Z=self.sc.transform(D[proc]);P=np.column_stack([Z**k for k in range(1,self.degree+1)])
  cols=[]
  for c,s,k in zip(active,p[:7],self.kind):
   x=D[c].values
   if k=='exp':v=1-np.exp(-x/s)
   if k=='rat':v=x/(s+x)
   if k=='log':v=np.log1p(x/s)
   if k=='tanh':v=np.tanh(x/s)
   if k=='root':v=np.sqrt(x+s)-np.sqrt(s)
   if k=='power':v=x**s
   cols.append(v)
  g=np.exp(-((D.aging_temp-p[7])/p[8])**2-((D.cooling_rate-p[9])/p[10])**2-((D.Mo-p[11])/p[12])**2)
  return np.column_stack([np.ones(len(D)),*cols,D[other],P,self.o.transform(D[cats]),g])
 def fit(self,D,y):
  init=np.array([6,6,1,.3,.2,4,.2,607,32,35,10,1.9,.6]);lo=np.array([.1,.1,.001,.005,.003,.01,.002,570,12,27,4,1.3,.2]);hi=np.array([100,200,20,10,10,100,10,640,70,43,25,2.5,1.5])
  for i,k in enumerate(self.kind):
   if k=='power':init[i]=.5;lo[i]=.1;hi[i]=1.4
  self.mat(init,D,True)
  def residual(p):
   A=self.mat(p,D);coef=np.linalg.lstsq(A,y,rcond=1e-8)[0];return y-A@coef
  opt=least_squares(residual,init,bounds=(lo,hi),max_nfev=200,ftol=1e-8)
  self.p=opt.x;self.coef=np.linalg.lstsq(self.mat(self.p,D),y,rcond=1e-8)[0];return self
 def predict(self,D):return self.mat(self.p,D)@self.coef
if __name__=='__main__':
 for kind in ['exp','rat','log','tanh','root','power']:
  p=np.zeros(len(y))
  for it,iv in kf.split(D):
   m=SaturationModel(kind).fit(D.iloc[it],y[it]);p[iv]=m.predict(D.iloc[iv])
  m.fit(D,y)
  print(kind,'CV',np.mean((y-p)**2)**.5,'train',np.mean((y-m.predict(D))**2)**.5,'params',m.p.round(4),'coefs',m.coef.round(4),flush=True)

from peak_model import *
active=['Cr','Ni','Mo','V','Nb','Co','Ti'];other=['C','Mn','Si','Al','Cu']
class SmoothPeak:
 def __init__(self,knots=4,trans='raw',alpha=0,other_mode='linear',quantile=False):
  self.knots=knots;self.trans=trans;self.alpha=alpha;self.other_mode=other_mode;self.quantile=quantile
 def mat(self,D,fit=False):
  C=D[active].values
  if self.trans=='sqrt':C=np.sqrt(C)
  elif self.trans=='log':C=np.log1p(C/np.array([1,1,.1,.03,.02,.3,.03]))
  if fit:
   self.sp=SplineTransformer(n_knots=self.knots,degree=3,knots='quantile' if self.quantile else 'uniform',include_bias=False).fit(C)
   self.o=OneHotEncoder(sparse_output=False,drop='first').fit(D[cats]);self.sc=StandardScaler().fit(D[proc])
  C=self.sp.transform(C);P=self.sc.transform(D[proc]);nuis=D[other].values
  if self.other_mode=='none':nuis=np.zeros((len(D),0))
  elif self.other_mode=='spline':
   if fit:self.spo=SplineTransformer(n_knots=3,include_bias=False).fit(nuis)
   nuis=self.spo.transform(nuis)
  A=np.column_stack([C,nuis,P,P*P,self.o.transform(D[cats])])
  if fit:self.scale=StandardScaler().fit(A)
  return np.column_stack([np.ones(len(D)),self.scale.transform(A)])
 def gauss(self,p,D):return np.exp(-((D.aging_temp-p[0])/p[1])**2-((D.cooling_rate-p[2])/p[3])**2-((D.Mo-p[4])/p[5])**2)
 def fit(self,D,y):
  A=self.mat(D,True);pen=np.diag(np.sqrt(np.full(A.shape[1],self.alpha)));pen[0,0]=0
  B=np.vstack([A,pen]);Ai=np.linalg.pinv(B,rcond=1e-8);yy=np.r_[y,np.zeros(A.shape[1])];yres=yy-B@(Ai@yy)
  def res(p):
   g=np.r_[self.gauss(p,D),np.zeros(A.shape[1])];gres=g-B@(Ai@g);amp=gres@yres/(gres@gres);return yres-amp*gres
  opt=least_squares(res,[607,32,35,10,1.9,.6],bounds=([570,12,27,4,1.3,.2],[640,70,43,25,2.5,1.5]),max_nfev=150,ftol=1e-8)
  self.p=opt.x;g=np.r_[self.gauss(self.p,D),np.zeros(A.shape[1])];gres=g-B@(Ai@g);self.amp=gres@yres/(gres@gres);self.coef=Ai@(yy-self.amp*g)
  return self
 def predict(self,D):return self.mat(D)@self.coef+self.amp*self.gauss(self.p,D)
if __name__=='__main__':
 results=[]
 for trans in ['raw','sqrt','log']:
  for knots in [3,4,5]:
   for alpha in [0,.1,1,10]:
    pp=np.zeros(len(y))
    for it,iv in kf.split(D):
     m=SmoothPeak(knots,trans,alpha).fit(D.iloc[it],y[it]);pp[iv]=m.predict(D.iloc[iv])
    results.append((np.mean((y-pp)**2)**.5,trans,knots,alpha))
    print(results[-1],flush=True)
 print('Best',sorted(results)[:10])

